from .money import MAX_CENTS, parse_cents, format_amount, _cents_to_decimal


def make_invoice(amounts):
    if not isinstance(amounts, list):
        raise ValueError("amounts must be a list")
    items = list(amounts)  # snapshot; the caller's list is never modified
    total = 0
    for item in items:
        total += parse_cents(item)
    if total > MAX_CENTS:
        raise ValueError("total too large")
    return {"total": format_amount(_cents_to_decimal(total)), "count": len(items)}

