import re
from decimal import Decimal

MAX_CENTS = 100000000  # 1000000.00
_STRING_RE = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?", re.ASCII)


def _cents_to_decimal(cents):
    # Built from a tuple so the result is exact whatever the active context is.
    digits = tuple(int(c) for c in str(cents))
    return Decimal((0, digits, -2))


def parse_cents(value):
    """Validate value and return it as an exact positive integer number of cents.

    Only integer arithmetic and context-independent Decimal operations are
    used, so the caller's decimal context can never affect the result.
    """
    if isinstance(value, bool):
        raise ValueError("invalid amount")
    if isinstance(value, str):
        if _STRING_RE.fullmatch(value) is None:
            raise ValueError("invalid amount")
        value = Decimal(value)  # string conversion is always exact
    elif isinstance(value, int):
        value = Decimal(value)
    elif not isinstance(value, Decimal):
        raise ValueError("invalid amount")

    if not value.is_finite():
        raise ValueError("invalid amount")
    if value <= 0:  # zero (including -0) and negatives
        raise ValueError("amount must be positive")
    if value > MAX_CENTS // 100:  # comparisons are exact
        raise ValueError("amount too large")

    _sign, digits, exp = value.as_tuple()
    shift = -2 - exp  # number of digits to drop to reach cents
    if shift > 0:
        dropped = digits[len(digits) - shift:] if shift <= len(digits) else digits
        if shift > len(digits) or any(dropped):
            raise ValueError("amount not representable in cents")
        digits = digits[:len(digits) - shift]
        cents = int("".join(map(str, digits))) if digits else 0
    else:
        cents = int("".join(map(str, digits))) * 10 ** (-shift)

    if cents <= 0 or cents > MAX_CENTS:
        raise ValueError("amount out of range")
    return cents


def parse_amount(value):
    return _cents_to_decimal(parse_cents(value))


def format_amount(value):
    return format(value, ".2f")
